function endCheck(lesson){if(paused({lesson})){toast('This topic’s automatic check is paused. Previous work is preserved; no new completion is awarded.');return;}const qid='c'+lesson.replace('.',''),r=S.r['s-'+qid];if(!r?.a.length){toast('Try the lesson-check answer before recording the check.');return;}if(!(S.reasons[lesson]||'').trim()&&!S.paper[lesson]){toast('Add a short explanation or indicate that you kept your reasoning on paper.');$('#reason-'+lesson.replace('.','\\.'))?.focus();return;}if(!S.done.includes(lesson))S.done.push(lesson);save();updateProgress();toast('Lesson check recorded. This is not a grade or assignment submission.');}
