function area(){const p=Number($('[data-area-p]').value),q=Number($('[data-area-q]').value);$('[data-p-label]').textContent=p;$('[data-q-label]').textContent=q;$('[data-area-top]').textContent=q;$('[data-cell-q]').textContent=q+'x';$('[data-cell-p]').textContent=p+'x';$('[data-cell-c]').textContent=p*q;$('[data-area-equation]').innerHTML=pretty('(x + '+p+')(x + '+q+') = x^2 + '+(p+q)+'x + '+(p*q));$('[data-area-summary]').textContent='The x strips add to '+(p+q)+'x. The corner has area '+(p*q)+'.';$('[data-area-grid]').setAttribute('aria-label','Four rectangular regions: x squared, '+q+'x, '+p+'x, and '+(p*q)+'. Rows have heights x and '+p+'; columns have widths x and '+q+'.');}
function markExpressionExposure(expression){try{const sig=C.signature({expression}),q=D.questions.find(q=>C.signature(q)===sig);if(q){expose(q.id,8);save();}}catch{}}
function markAreaExposure(){const p=Number($('[data-area-p]').value),q=Number($('[data-area-q]').value);markExpressionExposure('(x+'+p+')(x+'+q+')');}
function markGridExposure(){const v=Object.fromEntries($$('[data-grid-coef]').map(e=>[e.dataset.gridCoef,Number(e.value)]));markExpressionExposure('('+v.a+'x+('+v.b+'))('+v.c+'x+('+v.d+'))');}
function numberLab(){const a=Number($('#number-a').value),b=Number($('#number-b').value),o=$('#number-output');o.hidden=false;if(!Number.isInteger(a)||!Number.isInteger(b)||a<2||b<2||a>10000||b>10000){o.textContent='Enter whole numbers from 2 to 10,000.';return;}const g=M.gcd(a,b),sq=Math.sqrt(a),cb=Math.round(Math.cbrt(a));o.innerHTML='<p>'+a+' = '+M.primes(a).join(' × ')+'</p><p>'+b+' = '+M.primes(b).join(' × ')+'</p><p><strong>GCF = '+g+'; LCM = '+(a/g*b)+'.</strong></p><p>'+a+(Number.isInteger(sq)?' is a perfect square: √'+a+' = '+sq: ' is not a perfect square; its square root lies between '+Math.floor(sq)+' and '+Math.ceil(sq))+'.</p><p>'+a+(cb**3===a?' is a perfect cube: ∛'+a+' = '+cb:' is not a perfect cube')+'.</p>';}
function grid(){const v=Object.fromEntries($$('[data-grid-coef]').map(e=>[e.dataset.gridCoef,Number(e.value)]));if(Object.values(v).some(n=>!Number.isInteger(n)||n<-9||n>9))return;const{a,b,c,d}=v;const expr='('+a+'x'+(b<0?b:'+'+b)+')('+c+'x'+(d<0?d:'+'+d)+')';$('#expansion-grid').innerHTML='<div class="equation">'+pretty(expr)+'</div><div class="table-wrap"><table><tr><th>×</th><th>'+c+'x</th><th>'+d+'</th></tr><tr><th>'+a+'x</th><td>'+a*c+'x²</td><td>'+a*d+'x</td></tr><tr><th>'+b+'</th><td>'+b*c+'x</td><td>'+b*d+'</td></tr></table></div><p>Combine the middle products: '+(a*d)+'x + ('+(b*c)+')x = '+(a*d+b*c)+'x.</p><div class="equation">'+pretty(M.fmt(M.parse(expr).p))+'</div>';}
