// The first complete mastery workshop is Lesson 3.6. It observes four
// separate components instead of inferring an intermediate method from a
// correct final factorization.
let mastery36Task=null,mastery36RequestedMode=null;
function mastery36Mode(){const targets=Mastery.evaluate(S.mastery).targets.filter(t=>t.lesson==='3.6');if(targets.some(t=>t.pendingRecheck&&(!S.mastery.gaps[t.id]?.kind||S.mastery.gaps[t.id]?.kind==='execution'))||targets.some(t=>t.confirmedGap==='execution'||t.stage<50))return'verification';if(targets.some(t=>S.mastery.gaps[t.id]?.pending&&S.mastery.gaps[t.id]?.kind==='reasoning')||targets.some(t=>t.confirmedGap==='reasoning'||t.stage<75))return'transfer';return'retention';}
function m36RecheckActions(targets){return'<div class="actions">'+(targets.some(t=>t.stage>=50)?'<button class="button secondary" id="m36-recheck-verification" type="button">Recheck an independent skill</button>':'')+(targets.some(t=>t.stage>=75)?'<button class="button secondary" id="m36-recheck-transfer" type="button">Try a different changed-form check</button>':'')+'</div>';}
function m36StageText(t){if(t.confirmedGap)return'Confirmed '+t.confirmedGap+' gap · use a fresh check';if(t.pendingRecheck)return'Fresh recheck needed';return t.stage===0?'Not yet shown':t.stage===25?'First independent success':t.stage===50?'Consistent independence':t.stage===75?'Transfer shown':'Later evidence shown';}
function mastery36Variant(mode){const saved=S.mastery.workshop;if(saved?.mode===mode&&H36.variants[saved.index])return{index:saved.index,problem:H36.problem(H36.variants[saved.index]),id:saved.id,values:saved.values,fresh:saved.fresh===true,support:saved.support||0};
 const used=new Set(S.mastery.seen36||[]),exposed=new Set([...S.seen,...S.exposed].map(id=>Q[id]&&C.signature(Q[id])));
 let choice=null,highest=-1;const ids=['C3-36a','C3-36b','C3-36c','C3-36d'];
 for(let index=0;index<H36.variants.length;index++){const problem=H36.problem(H36.variants[index]);if((mode==='transfer'||mode==='retention')&&problem.g===1)continue;if(used.has(index)||exposed.has(C.signature({expression:problem.poly}))||masteryPriorExposure(36,problem))continue;
  const novelty=ids.reduce((count,id)=>count+Number(!S.mastery.receipts.some(r=>r.target===id&&r.kind===mode&&r.correct&&r.variation===H36.variation(id,problem))),0);
  if(novelty>highest){highest=novelty;choice={index,problem,id:'m36-'+mode+'-v'+(index+1),values:{},fresh:true,support:0};if(novelty===4&&mode!=='verification')break;}}
 return choice;}
