function m32RepairSteps(problem,checked){
 if(!checked||checked.status!=='checked')return[
  'For each exact root, find the positive whole number whose square or cube gives the number in this task.',
  'For the non-perfect root, compare powers of consecutive whole numbers and then estimate to one decimal place.',
  'For area or volume, give the length in cm and show a power equality that checks it.'
 ];
 const wrong=Object.entries(checked.correct).filter(([,okay])=>!okay).map(([id])=>id);
 if(!wrong.length)return['All four parts of that task were correct. Use a different fresh check to build further independent evidence.'];
 return wrong.map(id=>{
  if(id==='C3-32a')return`Square root: ${problem.squareRoot}² = ${problem.squareRoot**2}, so the positive root of ${problem.squareRoot**2} is ${problem.squareRoot}.`;
  if(id==='C3-32b')return`Cube root: ${problem.cubeRoot}³ = ${problem.cubeRoot**3}, so the cube root of ${problem.cubeRoot**3} is ${problem.cubeRoot}.`;
  if(id==='C3-32c')return`Bounds and estimate: ${problem.lower}^${problem.degree} = ${problem.lowerPower} and ${problem.upper}^${problem.degree} = ${problem.upperPower}. ${problem.radicand} lies between those powers, so its ${problem.degree===2?'square':'cube'} root is between ${problem.lower} and ${problem.upper}; to one decimal place it is ${problem.estimate.toFixed(1)}.`;
  return`Dimension and units: a ${problem.context==='area'?'square area':'cube volume'} of ${problem.measure} ${problem.context==='area'?'cm²':'cm³'} has a length of ${problem.dimension} cm. Check it with ${problem.dimension}^${problem.context==='area'?2:3}=${problem.measure}.`;
 });
}
