function syncTrig(){const T=S.trig||{};for(const [id,key]of [['trig-side','side'],['trig-adjacent','adjacent'],['trig-hypotenuse','hypotenuse'],['trig-ratio','ratio'],['trig-angle','angleRaw'],['trig-length','lengthRaw'],['trig-length-ratio','length'],['trig-reason','reason']])$('#'+id).value=T[key]||'';const angle=(T.rotation||0)*90;$('#trig-shape').setAttribute('transform','rotate('+angle+' 180 120)');for(const text of $$('#trig-shape text'))text.setAttribute('transform','rotate('+(-angle)+' '+text.getAttribute('x')+' '+text.getAttribute('y')+')');
 for(const [kind,key,raw]of [['angle','aa','angleRaw'],['length','la','lengthRaw']]){const a=T[key]?.at(-1);if(T[raw])trigFeedback('#trig-'+kind+'-feedback',a&&a[1]===T[raw]?{status:a[2],detail:'Retained response '+a[1]+': '+(a[4]?.value?.detail||'Legacy result; chronology is uncertain and was not regraded.')+' Setup: '+(a[4]?.setup||'legacy unknown')}:{status:'ungraded',detail:'Current draft has not been checked.'});}}
document.addEventListener('toggle',e=>{if(e.target.matches('[data-support-q]')&&e.target.open&&!blocked){expose(e.target.dataset.supportQ,2);save();}if(e.target.id==='trig-angle-support'&&e.target.open&&!blocked){S.trig.angleSupport=trigSupport('angle')|2;save();}},true);
document.addEventListener('input',e=>{const map={'trig-angle':'angleRaw','trig-length':'lengthRaw','trig-reason':'reason'};if(map[e.target.id]&&!blocked){S.trig[map[e.target.id]]=e.target.value;if(e.target.id!=='trig-reason')trigFeedback('#'+(e.target.id==='trig-angle'?'trig-angle':'trig-length')+'-feedback',{status:'ungraded',detail:'Current draft has not been checked.'});save();}});
document.addEventListener('change',e=>{const map={'trig-side':'side','trig-adjacent':'adjacent','trig-hypotenuse':'hypotenuse','trig-ratio':'ratio','trig-length-ratio':'length'};if(map[e.target.id]&&!blocked){S.trig[map[e.target.id]]=e.target.value;S.trig.setupSaved=false;trigFeedback('#trig-setup-feedback',{status:'ungraded',detail:'Current setup has not been checked.'});save();}});
document.addEventListener('click',e=>{if(blocked)return;const id=e.target.closest('button')?.id;
 if(id==='trig-rotate'){S.trig.rotation=((S.trig.rotation||0)+1)%4;syncTrig();save();}
 if(id==='trig-setup'){const setup=trigSetup('angle'),before=trigSupport('angle');if(!S.trig.side||!S.trig.adjacent||!S.trig.hypotenuse||!S.trig.ratio){trigFeedback('#trig-setup-feedback',{status:'input',detail:'Choose all three sides and a ratio before checking the setup.'});return;}retainSetup('angle',setup,before);S.trig.setupSaved=setup.status==='correct';trigFeedback('#trig-setup-feedback',{status:setup.status,detail:setup.status==='correct'?'The three sides and tangent relationship fit. Now calculate the angle.':'Use the marked angle as reference. Check the side across from it, the other leg, and the side opposite the right angle.'});applyTrigFeedback('angle',{status:'not_attempted'},setup);save();}
 if(id==='trig-angle-check'||id==='trig-length-check'){const kind=id==='trig-angle-check'?'angle':'length',raw=S.trig[kind+'Raw']||'',before=trigSupport(kind),setup=trigSetup(kind);
  if(setup.status==='not_attempted'||(kind==='angle'&&(!S.trig.side||!S.trig.adjacent||!S.trig.hypotenuse))){trigFeedback('#trig-'+kind+'-feedback',{status:'input',detail:'Select the requested sides and relationship before checking the value.'});return;}
  const result=C.trig(raw,kind==='length'?{kind:'length'}:{});
  if(result.status==='input'){if(!raw.trim())retainSetup(kind,setup,before);trigFeedback('#trig-'+kind+'-feedback',{status:'input',detail:'The numeric entry needs repair. '+(raw.trim()?'No mathematical submission was counted.':'Only your setup was recorded; no numeric attempt was counted.')});if(!raw.trim())applyTrigFeedback(kind,{status:'not_attempted'},setup);save();return;}
  retainTrig(kind,raw,result,setup,before);S.trig[kind==='angle'?'angle':'lengthStatus']=result.status;
  trigFeedback('#trig-'+kind+'-feedback',{status:result.status,detail:result.detail+' Setup: '+(setup.status==='correct'?'the selected relationship fits.':'the relationship needs repair; a correct number does not replace it.')});applyTrigFeedback(kind,result,setup);save();}
});
